import json, subprocess, sys, random
sys.setrecursionlimit(1000000)

def run(reqs):
    data = b"\n".join(json.dumps(r).encode() for r in reqs)
    p = subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,
                       stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    if p.returncode!=0:
        print("RC",p.returncode,p.stderr.decode()); sys.exit(1)
    return [json.loads(x) for x in p.stdout.splitlines()]

class LIM(Exception): pass

def ref_replay(req):
    inputs=req["inputs"]; P=len(inputs); R=len(inputs[0]) if P else 0; D=len(inputs[0][0]) if R else 0
    slots=req["slots"]; window=req["window"]; events=req["events"]
    sent=[0]*P; received=[[] for _ in range(P)]; up_next=[0]*P; acked=[0]*P; floor=0
    # buffer list of physical slots
    buf=[None]*slots   # each None or dict(seq,ranks set,sum list)
    pending={}; nid=0; total=0
    def create(kind,rank,seq,value):
        nonlocal nid,total
        pid=nid; nid+=1; total+=1
        if total>200000: raise LIM()
        pending[pid]={"id":pid,"kind":kind,"rank":rank,"seq":seq,"value":value}
        if len(pending)>2048: raise LIM()
        return pid
    def find_entry(q):
        ph=q%slots
        e=buf[ph]
        if e is not None and e["seq"]==q: return e
        return None
    def make_entry(q):
        ph=q%slots
        e={"seq":q,"ranks":set(),"sum":[0]*D}
        buf[ph]=e
        return e
    evres=[]
    for ev in events:
        act=ev[0]; created=[]; status="ok"
        if act=="send":
            r=ev[1]; q=ev[2]
            if sent[r]<=q<min(R,sent[r]+window):
                created.append(create("up",r,q,inputs[r][q]))
            else: status="disabled"
        elif act=="retry":
            r=ev[1]
            fulls=[e for e in buf if e is not None and len(e["ranks"])==P and e["seq"]>=acked[r]]
            fulls.sort(key=lambda e:e["seq"])
            for e in fulls:
                created.append(create("down",r,e["seq"],list(e["sum"])))
        else:
            pid=ev[1]
            if pid not in pending:
                status="missing"
            else:
                pkt=pending.pop(pid)
                if act=="drop": pass
                elif act=="duplicate":
                    created.append(create(pkt["kind"],pkt["rank"],pkt["seq"],pkt["value"]))
                else:
                    k=pkt["kind"]
                    if k=="up":
                        r=pkt["rank"];q=pkt["seq"];val=pkt["value"]
                        if floor<=q<floor+slots:
                            e=find_entry(q)
                            if e is None: e=make_entry(q)
                            newly=False
                            if r not in e["ranks"]:
                                e["ranks"].add(r)
                                for i in range(D): e["sum"][i]+=val[i]
                                newly=True
                            while True:
                                ee=find_entry(up_next[r])
                                if ee is not None and r in ee["ranks"]: up_next[r]+=1
                                else: break
                            created.append(create("uack",r,up_next[r],None))
                            if newly and len(e["ranks"])==P:
                                for rr in range(P):
                                    created.append(create("down",rr,q,list(e["sum"])))
                        else:
                            created.append(create("uack",r,up_next[r],None))
                    elif k=="uack":
                        r=pkt["rank"];kk=pkt["seq"]
                        sent[r]=max(sent[r],kk)
                    elif k=="down":
                        r=pkt["rank"];q=pkt["seq"];val=pkt["value"]
                        if q==len(received[r]): received[r].append(val)
                        created.append(create("dack",r,len(received[r]),None))
                    elif k=="dack":
                        r=pkt["rank"];kk=pkt["seq"]
                        acked[r]=max(acked[r],kk)
                        floor=min(acked)
                        for ph in range(slots):
                            e=buf[ph]
                            if e is not None and e["seq"]<floor: buf[ph]=None
        evres.append({"status":status,"created":created})
    hosts=[{"sent":sent[r],"received":received[r]} for r in range(P)]
    sl=[]
    for e in buf:
        if e is not None:
            sl.append(e)
    sl.sort(key=lambda e:e["seq"])
    slots_out=[{"seq":e["seq"],"ranks":sorted(e["ranks"]),"sum":e["sum"]} for e in sl]
    packets=[pending[i] for i in sorted(pending)]
    return {"hosts":hosts,"floor":floor,"slots":slots_out,"packets":packets,"events":evres}

