bad=0;tot=0
for trial in range(4000):
    P=random.randint(1,3); R=random.randint(0,4); D=random.randint(0,2)
    inputs=[[[random.randint(-3,3) for _ in range(D)] for _ in range(R)] for _ in range(P)]
    slots=random.randint(1,4); window=random.randint(1,slots)
    # build event stream
    events=[]
    maxid=0
    n_ev=random.randint(0,25)
    for _ in range(n_ev):
        choices=["send"]
        if R>0: choices.append("send")
        choices+=["retry","deliver","drop","duplicate"]
        t=random.choice(choices)
        if t=="send":
            if R==0:
                events.append(["retry",random.randrange(P)]); continue
            events.append(["send",random.randrange(P),random.randrange(R)])
        elif t=="retry":
            events.append(["retry",random.randrange(P)])
        else:
            events.append([t,random.randint(0,max(maxid+2,2))])
            maxid+=1  # rough
    req={"op":"replay","inputs":inputs,"slots":slots,"window":window,"events":events}
    # Only compare when neither raises LIM (we detect via resp error)
    resp=run([req])[0]
